INSERT INTO "articles" ("title", "summary", "content", "image_url", "approved", "likes", "author_id", "created_at", "updated_at") SELECT 'Night Court closes in five', 'Tide Breakers steal the last set and the trophy under the black lights.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A final that would not end"}]},{"type":"paragraph","content":[{"type":"text","text":"Harbor packed the stands for a five-set grind that felt like it belonged in a later season."}]},{"type":"paragraph","content":[{"type":"text","text":"Iris Cho ran the offense until the last rotation, then let Juno Vale close on the pipe."}]},{"type":"paragraph","content":[{"type":"text","text":"Iron Setters had match point twice. They will be back. The desk already has the clip."}]}]}', '/images/s12.png', 1, 18, 'seed-the-entity', 1785118200000, 1785118200000 WHERE NOT EXISTS (SELECT 1 FROM "articles" WHERE "title" = 'Night Court closes in five');
INSERT INTO "articles" ("title", "summary", "content", "image_url", "approved", "likes", "author_id", "created_at", "updated_at") SELECT 'Floodlights open with a statement', 'Volt Diggers sweep Sand Kings and book a semi.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The lights stay on"}]},{"type":"paragraph","content":[{"type":"text","text":"Season four''s quarter-finals opened the way the preview said they would: loud, short, and one-sided."}]},{"type":"paragraph","content":[{"type":"text","text":"Uma Reed put up 28 kills. The block held on the second sideout after the timeout."}]},{"type":"paragraph","content":[{"type":"text","text":"Sand Kings never found a sideout run. Volt wait in the last four."}]}]}', '/images/top-10-wing-spikers.jpg', 1, 27, 'seed-the-entity', 1786066800000, 1786066800000 WHERE NOT EXISTS (SELECT 1 FROM "articles" WHERE "title" = 'Floodlights open with a statement');
