INSERT INTO "articles" ("title", "summary", "content", "image_url", "approved", "likes", "author_id", "created_at", "updated_at") SELECT 'The libero watch list', 'Four names the desk cannot stop clipping as playoffs start.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hands first"}]},{"type":"paragraph","content":[{"type":"text","text":"Mae Frost is the obvious one. The other three are quieter and maybe more dangerous."}]},{"type":"paragraph","content":[{"type":"text","text":"If you only watch the highlights you will miss the digs that start the points."}]}]}', '/images/s6.png', 1, 9, 'seed-the-entity', 1786724400000, 1786724400000 WHERE NOT EXISTS (SELECT 1 FROM "articles" WHERE "title" = 'The libero watch list');
